files.content:
:root {
    /* Dark Theme (Default) */
    --bg-base: #090e17;
    --bg-surface: #111827;
    --text-main: #f8fafc;
    --text-muted: #94a3b8;
    --border: #1f2937;
    --border-hover: #374151;
    --accent: #00e6d2;
    --accent-hover: #00c4b3;
    --accent-muted: rgba(0, 230, 210, 0.1);
    --amber: #f59e0b;
    --amber-muted: rgba(245, 158, 11, 0.15);
    --font-family: 'Inter', system-ui, -apple-system, sans-serif;
    --radius: 12px;
    --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.2), 0 2px 4px -2px rgba(0, 0, 0, 0.2);
}

[data-theme="light"] {
    --bg-base: #f1f5f9;
    --bg-surface: #ffffff;
    --text-main: #0f172a;
    --text-muted: #64748b;
    --border: #e2e8f0;
    --border-hover: #cbd5e1;
    --accent: #0d9488;
    --accent-hover: #0f766e;
    --accent-muted: rgba(13, 148, 136, 0.1);
    --amber: #d97706;
    --amber-muted: rgba(217, 119, 6, 0.15);
    --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -2px rgba(0, 0, 0, 0.025);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: var(--font-family);
    background-color: var(--bg-base);
    color: var(--text-main);
    -webkit-font-smoothing: antialiased;
    overflow: hidden;
}

.app-container {
    display: flex;
    height: 100vh;
    width: 100vw;
}

/* Sidebar */
.sidebar {
    width: 240px;
    background-color: var(--bg-surface);
    border-right: 1px solid var(--border);
    display: flex;
    flex-direction: column;
    padding: 24px 16px;
    z-index: 10;
}

.brand {
    display: flex;
    align-items: center;
    gap: 12px;
    font-size: 1.25rem;
    font-weight: 600;
    color: var(--text-main);
    margin-bottom: 40px;
    padding: 0 8px;
}

.nav-menu {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.nav-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 12px;
    text-decoration: none;
    color: var(--text-muted);
    border-radius: 8px;
    font-weight: 500;
    font-size: 0.9rem;
    transition: all 0.2s;
}

.nav-item:hover {
    background-color: var(--bg-base);
    color: var(--text-main);
}

.nav-item.active {
    background-color: var(--accent-muted);
    color: var(--accent);
}

/* Main Content */
.main-content {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.topbar {
    height: 72px;
    padding: 0 32px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    border-bottom: 1px solid var(--border);
    background-color: rgba(var(--bg-surface), 0.8);
    backdrop-filter: blur(12px);
    z-index: 5;
}

.topbar-title h1 {
    font-size: 1.25rem;
    font-weight: 600;
}

.topbar-controls {
    display: flex;
    align-items: center;
    gap: 16px;
}

.control-select {
    background-color: var(--bg-base);
    color: var(--text-main);
    border: 1px solid var(--border);
    padding: 8px 12px;
    border-radius: 6px;
    font-family: inherit;
    font-size: 0.875rem;
    outline: none;
    cursor: pointer;
}

.control-select:focus {
    border-color: var(--accent);
}

.segmented-control {
    display: flex;
    background-color: var(--bg-base);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 2px;
}

.segmented-control button {
    background: transparent;
    border: none;
    color: var(--text-muted);
    padding: 6px 12px;
    font-size: 0.875rem;
    font-weight: 500;
    border-radius: 4px;
    cursor: pointer;
    transition: all 0.2s;
}

.segmented-control button:hover {
    color: var(--text-main);
}

.segmented-control button.active {
    background-color: var(--bg-surface);
    color: var(--text-main);
    box-shadow: 0 1px 2px rgba(0,0,0,0.1);
}

.icon-btn {
    background: transparent;
    border: 1px solid var(--border);
    color: var(--text-muted);
    width: 36px;
    height: 36px;
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.2s;
}

.icon-btn:hover {
    color: var(--text-main);
    border-color: var(--border-hover);
}

[data-theme="dark"] .moon-icon { display: none; }
[data-theme="light"] .sun-icon { display: none; }

.content-scroll {
    flex: 1;
    overflow-y: auto;
    padding: 32px;
    display: flex;
    flex-direction: column;
    gap: 24px;
}

/* Cards */
.card {
    background-color: var(--bg-surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 24px;
    box-shadow: var(--shadow);
}

.card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
}

.card-header h2 {
    font-size: 1rem;
    font-weight: 600;
    color: var(--text-main);
}

/* KPIs */
.kpi-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 24px;
}

.kpi-title {
    font-size: 0.875rem;
    font-weight: 500;
    color: var(--text-muted);
    margin-bottom: 12px;
}

.kpi-value {
    font-size: 2rem;
    font-weight: 600;
    color: var(--text-main);
    margin-bottom: 12px;
}

.kpi-delta {
    display: inline-flex;
    align-items: center;
    padding: 4px 8px;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 600;
    background-color: var(--amber-muted);
    color: var(--amber);
}

/* Charts */
.charts-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 24px;
}

.chart-card.span-2 {
    grid-column: span 2;
}

.chart-container {
    position: relative;
    height: 260px;
    width: 100%;
}

/* Table */
.table-header {
    margin-bottom: 16px;
}

.search-box {
    display: flex;
    align-items: center;
    gap: 8px;
    background-color: var(--bg-base);
    border: 1px solid var(--border);
    padding: 6px 12px;
    border-radius: 6px;
}

.search-box svg {
    color: var(--text-muted);
}

.search-box input {
    background: transparent;
    border: none;
    color: var(--text-main);
    font-family: inherit;
    font-size: 0.875rem;
    outline: none;
    width: 200px;
}

.table-responsive {
    overflow-x: auto;
}

table {
    width: 100%;
    border-collapse: collapse;
    text-align: left;
}

th, td {
    padding: 12px 16px;
    border-bottom: 1px solid var(--border);
    font-size: 0.875rem;
}

th {
    color: var(--text-muted);
    font-weight: 500;
    cursor: pointer;
    user-select: none;
    transition: color 0.2s;
}

th:hover {
    color: var(--text-main);
}

th .sort-icon {
    width: 14px;
    height: 14px;
    vertical-align: middle;
    opacity: 0.3;
    margin-left: 4px;
}

th.sort-asc .sort-icon,
th.sort-desc .sort-icon {
    opacity: 1;
    color: var(--accent);
}

th.sort-asc .sort-icon path:last-child { display: none; }
th.sort-desc .sort-icon path:first-child { display: none; }

td {
    color: var(--text-main);
}

tbody tr:last-child td {
    border-bottom: none;
}

tbody tr:hover td {
    background-color: rgba(255, 255, 255, 0.02);
}

[data-theme="light"] tbody tr:hover td {
    background-color: rgba(0, 0, 0, 0.02);
}

.text-right {
    text-align: right;
}

.badge {
    display: inline-block;
    padding: 2px 8px;
    border-radius: 12px;
    font-size: 0.75rem;
    font-weight: 500;
    background-color: var(--bg-base);
    border: 1px solid var(--border);
}

.delta-cell {
    color: var(--amber);
    font-weight: 500;
}

// Seeded PRNG for consistent data generation
let seed = 1029384756;
function random() {
    let t = seed += 0x6D2B79F5;
    t = Math.imul(t ^ t >>> 15, t | 1);
    t ^= t + Math.imul(t ^ t >>> 7, t | 61);
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
}

function randomInt(min, max) {
    return Math.floor(random() * (max - min + 1)) + min;
}

function randomChoice(arr) {
    return arr[Math.floor(random() * arr.length)];
}

const plans = ['Starter', 'Growth', 'Enterprise'];
const regions = ['EMEA', 'Americas', 'APAC'];

const companyNames = [
    "Acme Corp", "Globalex", "Initech", "Umbrella Corp", "Stark Ind", 
    "Wayne Ent", "Cyberdyne", "Massive Dynamic", "Hooli", "Pied Piper",
    "Soylent", "InGen", "Tyrell Corp", "Weyland-Yutani", "Omni CP",
    "Gekko & Co", "Dunder Mifflin", "Vandelay Ind", "Bluth Co", "Strickland Prop",
    "MacMillan Toys", "Sterling Cooper", "Pierce & Pierce", "Kramerica", "Oceanic",
    "Virtucon", "Globex", "Rekall", "Buy n Large", "Monsters Inc",
    "Spacely Sprockets", "Cogswell Cogs", "CHOAM", "Sirius Cybernetics", "Slurm",
    "MomCorp", "Planet Express", "LexCorp", "Oscorp", "Daily Bugle"
];

// Generate 40 Customers
const customers = companyNames.map((name, i) => {
    const plan = randomChoice(plans);
    const region = randomChoice(regions);

    let baseMRR = 0;
    let seats = 0;
    if (plan === 'Starter') {
        baseMRR = randomInt(100, 500);
        seats = randomInt(1, 10);
    } else if (plan === 'Growth') {
        baseMRR = randomInt(600, 2000);
        seats = randomInt(11, 50);
    } else {
        baseMRR = randomInt(2500, 10000);
        seats = randomInt(51, 250);
    }

    const growth = (random() * 0.4) - 0.1; // -10% to +30%

    return {
        id: `CUST-${1000 + i}`,
        name,
        plan,
        region,
        seats,
        mrr: baseMRR,
        growth: growth
    };
});

// Generate 365 days of historical data
const history = [];
const endDate = new Date('2024-01-01T00:00:00Z');

// Initial state 1 year ago
let currentMetrics = {
    EMEA: { Starter: 4000, Growth: 15000, Enterprise: 35000 },
    Americas: { Starter: 6000, Growth: 22000, Enterprise: 55000 },
    APAC: { Starter: 3000, Growth: 10000, Enterprise: 20000 }
};

let activeCustomers = 850;

for (let i = 365; i >= 0; i--) {
    const d = new Date(endDate);
    d.setDate(d.getDate() - i);

    const dayData = {
        date: d.toISOString().split('T')[0],
        metrics: JSON.parse(JSON.stringify(currentMetrics)),
        activeCustomers: activeCustomers
    };
    history.push(dayData);

    // Simulate daily growth/churn
    regions.forEach(r => {
        plans.forEach(p => {
            // Slight upward trend with random noise
            const change = (random() * 0.004) - 0.0015; 
            currentMetrics[r][p] = Math.max(0, currentMetrics[r][p] * (1 + change));
        });
    });

    // Customer count changes slowly
    if (random() > 0.8) {
        activeCustomers += randomInt(-1, 3);
    }
}

window.NorthwindData = {
    customers,
    history
};

document.addEventListener('DOMContentLoaded', () => {
    // --- State ---
    let state = {
        range: 30, // 30, 90, 365
        region: 'All', // All, EMEA, Americas, APAC
        theme: localStorage.getItem('theme') || 'dark',
        sortCol: 'mrr',
        sortDesc: true,
        searchQuery: ''
    };

    // --- Chart Instances ---
    let charts = {
        mrr: null,
        plan: null,
        region: null
    };

    // --- DOM Elements ---
    const els = {
        themeToggle: document.getElementById('theme-toggle'),
        regionFilter: document.getElementById('region-filter'),
        dateRangeBtns: document.querySelectorAll('#date-range button'),
        searchInput: document.getElementById('customer-search'),
        tableHeaders: document.querySelectorAll('th[data-sort]'),
        tableBody: document.getElementById('table-body'),
        kpi: {
            mrr: document.getElementById('kpi-mrr'),
            deltaMrr: document.getElementById('delta-mrr'),
            customers: document.getElementById('kpi-customers'),
            deltaCustomers: document.getElementById('delta-customers'),
            churn: document.getElementById('kpi-churn'),
            deltaChurn: document.getElementById('delta-churn'),
            nrr: document.getElementById('kpi-nrr'),
            deltaNrr: document.getElementById('delta-nrr')
        }
    };

    // --- Initialization ---
    function init() {
        applyTheme(state.theme);
        bindEvents();
        updateDashboard();
    }

    // --- Event Binding ---
    function bindEvents() {
        els.themeToggle.addEventListener('click', () => {
            state.theme = state.theme === 'dark' ? 'light' : 'dark';
            localStorage.setItem('theme', state.theme);
            applyTheme(state.theme);
            updateDashboard(); // Re-render charts for colors
        });

        els.regionFilter.addEventListener('change', (e) => {
            state.region = e.target.value;
            updateDashboard();
        });

        els.dateRangeBtns.forEach(btn => {
            btn.addEventListener('click', (e) => {
                els.dateRangeBtns.forEach(b => b.classList.remove('active'));
                e.target.classList.add('active');
                state.range = parseInt(e.target.dataset.value);
                updateDashboard();
            });
        });

        els.searchInput.addEventListener('input', (e) => {
            state.searchQuery = e.target.value.toLowerCase();
            renderTable();
        });

        els.tableHeaders.forEach(th => {
            th.addEventListener('click', () => {
                const col = th.dataset.sort;
                if (state.sortCol === col) {
                    state.sortDesc = !state.sortDesc;
                } else {
                    state.sortCol = col;
                    state.sortDesc = true;
                }
                updateTableHeaders();
                renderTable();
            });
        });
    }

    function applyTheme(theme) {
        document.documentElement.setAttribute('data-theme', theme);

        // Update Chart.js defaults
        const isDark = theme === 'dark';
        Chart.defaults.color = isDark ? '#94a3b8' : '#64748b';
        Chart.defaults.borderColor = isDark ? '#1f2937' : '#e2e8f0';
        Chart.defaults.font.family = "'Inter', system-ui, sans-serif";
    }

    // --- Data Processing & Rendering ---
    function updateDashboard() {
        const data = window.NorthwindData;
        const history = data.history;

        // Slice history based on range
        const periodData = history.slice(-state.range - 1); // +1 to get start value for deltas

        updateKPIs(periodData);
        updateCharts(periodData);
        renderTable();
    }

    function getMRRForDay(dayObj, regionFilter) {
        let total = 0;
        const regions = regionFilter === 'All' ? Object.keys(dayObj.metrics) : [regionFilter];
        regions.forEach(r => {
            if(dayObj.metrics[r]) {
                Object.values(dayObj.metrics[r]).forEach(val => total += val);
            }
        });
        return total;
    }

    function updateKPIs(periodData) {
        const startDay = periodData[0];
        const endDay = periodData[periodData.length - 1];

        // MRR
        const startMRR = getMRRForDay(startDay, state.region);
        const endMRR = getMRRForDay(endDay, state.region);
        const mrrDelta = ((endMRR - startMRR) / startMRR) * 100;

        // Customers (Simulated region split for demo purposes, total active is global in dataset)
        const regionMult = state.region === 'All' ? 1 : 0.33;
        const startCust = Math.floor(startDay.activeCustomers * regionMult);
        const endCust = Math.floor(endDay.activeCustomers * regionMult);
        const custDelta = startCust ? ((endCust - startCust) / startCust) * 100 : 0;

        // Churn & NRR (Simulated realistic metrics based on range)
        const baseChurn = state.region === 'All' ? 2.1 : (state.region === 'EMEA' ? 1.8 : 2.4);
        const churn = baseChurn * (state.range / 30);
        const churnDelta = (Math.random() * 0.4) - 0.2;

        const nrr = 104.5 + (Math.random() * 2);
        const nrrDelta = (Math.random() * 1.5) - 0.5;

        // Render
        els.kpi.mrr.textContent = formatCurrency(endMRR);
        renderDelta(els.kpi.deltaMrr, mrrDelta);

        els.kpi.customers.textContent = formatNumber(endCust);
        renderDelta(els.kpi.deltaCustomers, custDelta);

        els.kpi.churn.textContent = churn.toFixed(1) + '%';
        renderDelta(els.kpi.deltaChurn, churnDelta, true); // Lower is better

        els.kpi.nrr.textContent = nrr.toFixed(1) + '%';
        renderDelta(els.kpi.deltaNrr, nrrDelta);
    }

    function renderDelta(el, value, inverse = false) {
        const isPositive = value >= 0;
        const isGood = inverse ? !isPositive : isPositive;
        const sign = isPositive ? '+' : '';
        el.textContent = `${sign}${value.toFixed(1)}%`;
        // Using amber for all deltas as per design direction, but could toggle classes here if needed
    }

    function updateCharts(periodData) {
        const isDark = state.theme === 'dark';
        const accent = isDark ? '#00e6d2' : '#0d9488';
        const accentBg = isDark ? 'rgba(0, 230, 210, 0.1)' : 'rgba(13, 148, 136, 0.1)';

        // Destroy existing
        Object.values(charts).forEach(c => c && c.destroy());

        // 1. MRR Line Chart
        const labels = periodData.slice(1).map(d => formatDate(d.date));
        const mrrData = periodData.slice(1).map(d => getMRRForDay(d, state.region));

        const ctxMrr = document.getElementById('mrrChart').getContext('2d');
        charts.mrr = new Chart(ctxMrr, {
            type: 'line',
            data: {
                labels,
                datasets: [{
                    label: 'Total MRR',
                    data: mrrData,
                    borderColor: accent,
                    backgroundColor: accentBg,
                    borderWidth: 2,
                    fill: true,
                    tension: 0.4,
                    pointRadius: 0,
                    pointHitRadius: 20
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: { legend: { display: false }, tooltip: { mode: 'index', intersect: false } },
                scales: {
                    y: { beginAtZero: false, ticks: { callback: v => '$' + (v/1000).toFixed(0) + 'k' } },
                    x: { grid: { display: false }, ticks: { maxTicksLimit: 6 } }
                }
            }
        });

        // 2. Plan Stacked Bar Chart
        // Aggregate by month for the bar chart
        const monthlyData = {};
        periodData.slice(1).forEach(d => {
            const month = d.date.substring(0, 7); // YYYY-MM
            if (!monthlyData[month]) monthlyData[month] = { Starter: 0, Growth: 0, Enterprise: 0, count: 0 };

            const regions = state.region === 'All' ? Object.keys(d.metrics) : [state.region];
            let s=0, g=0, e=0;
            regions.forEach(r => {
                if(d.metrics[r]) {
                    s += d.metrics[r].Starter;
                    g += d.metrics[r].Growth;
                    e += d.metrics[r].Enterprise;
                }
            });
            monthlyData[month].Starter += s;
            monthlyData[month].Growth += g;
            monthlyData[month].Enterprise += e;
            monthlyData[month].count++;
        });

        const barLabels = Object.keys(monthlyData).map(m => {
            const d = new Date(m + '-01');
            return d.toLocaleDateString('en-US', { month: 'short' });
        });

        // Average per month to avoid summing daily MRR
        const starterData = Object.values(monthlyData).map(m => m.Starter / m.count);
        const growthData = Object.values(monthlyData).map(m => m.Growth / m.count);
        const enterpriseData = Object.values(monthlyData).map(m => m.Enterprise / m.count);

        const ctxPlan = document.getElementById('planChart').getContext('2d');
        charts.plan = new Chart(ctxPlan, {
            type: 'bar',
            data: {
                labels: barLabels,
                datasets: [
                    { label: 'Starter', data: starterData, backgroundColor: isDark ? '#1f2937' : '#cbd5e1' },
                    { label: 'Growth', data: growthData, backgroundColor: isDark ? '#374151' : '#94a3b8' },
                    { label: 'Enterprise', data: enterpriseData, backgroundColor: accent }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: { legend: { position: 'bottom', labels: { usePointStyle: true, boxWidth: 8 } } },
                scales: {
                    x: { stacked: true, grid: { display: false } },
                    y: { stacked: true, ticks: { callback: v => '$' + (v/1000).toFixed(0) + 'k' } }
                }
            }
        });

        // 3. Region Doughnut Chart
        const endDay = periodData[periodData.length - 1];
        const regionData = [];
        const regionLabels = ['EMEA', 'Americas', 'APAC'];

        regionLabels.forEach(r => {
            if (state.region === 'All' || state.region === r) {
                let total = 0;
                Object.values(endDay.metrics[r]).forEach(v => total += v);
                regionData.push(total);
            } else {
                regionData.push(0);
            }
        });

        const ctxRegion = document.getElementById('regionChart').getContext('2d');
        charts.region = new Chart(ctxRegion, {
            type: 'doughnut',
            data: {
                labels: regionLabels,
                datasets: [{
                    data: regionData,
                    backgroundColor: [
                        isDark ? '#1f2937' : '#cbd5e1',
                        isDark ? '#374151' : '#94a3b8',
                        accent
                    ],
                    borderWidth: 0
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                cutout: '75%',
                plugins: { legend: { position: 'bottom', labels: { usePointStyle: true, boxWidth: 8 } } }
            }
        });
    }

    function updateTableHeaders() {
        els.tableHeaders.forEach(th => {
            th.classList.remove('sort-asc', 'sort-desc');
            if (th.dataset.sort === state.sortCol) {
                th.classList.add(state.sortDesc ? 'sort-desc' : 'sort-asc');
            }
        });
    }

    function renderTable() {
        let filtered = window.NorthwindData.customers.filter(c => {
            const matchRegion = state.region === 'All' || c.region === state.region;
            const matchSearch = c.name.toLowerCase().includes(state.searchQuery);
            return matchRegion && matchSearch;
        });

        filtered.sort((a, b) => {
            let valA = a[state.sortCol];
            let valB = b[state.sortCol];

            if (typeof valA === 'string') valA = valA.toLowerCase();
            if (typeof valB === 'string') valB = valB.toLowerCase();

            if (valA < valB) return state.sortDesc ? 1 : -1;
            if (valA > valB) return state.sortDesc ? -1 : 1;
            return 0;
        });

        const top8 = filtered.slice(0, 8);

        els.tableBody.innerHTML = top8.map(c => `
            <tr>
                <td style="font-weight: 500;">${c.name}</td>
                <td><span class="badge">${c.plan}</span></td>
                <td>${c.region}</td>
                <td>${c.seats}</td>
                <td class="text-right">${formatCurrency(c.mrr)}</td>
                <td class="text-right delta-cell">${c.growth >= 0 ? '+' : ''}${(c.growth * 100).toFixed(1)}%</td>
            </tr>
        `).join('');

        if (top8.length === 0) {
            els.tableBody.innerHTML = `<tr><td colspan="6" style="text-align: center; color: var(--text-muted); padding: 32px;">No customers found matching criteria.</td></tr>`;
        }
    }

    // --- Utils ---
    function formatCurrency(num) {
        return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(num);
    }

    function formatNumber(num) {
        return new Intl.NumberFormat('en-US').format(num);
    }

    function formatDate(dateStr) {
        const d = new Date(dateStr);
        return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
    }

    // Run
    init();
});
